    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (i == 0 && j == 0) best[j] = cost[0][0];
            else if (i == 0) best[j] = best[j - 1] + cost[i][j];
            else if (j == 0) best[j] += cost[i][j];
            else best[j] = min(best[j], best[j - 1]) + cost[i][j];
        }
    }
    cout << best[w - 1] << "\n";

    return 0;
